// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/reviews", wrapper.ListProductReviews)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/reviews", wrapper.SubmitReview)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/reviews/stats", wrapper.GetReviewStats)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/reviews/mine", wrapper.ListMyReviews)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/reviews/{id}", wrapper.DeleteReview)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/reviews/{id}", wrapper.EditReview)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/likes", wrapper.ListMyLikes)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/likes/{product_id}", wrapper.UnlikeProduct)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/likes/{product_id}", wrapper.LikeProduct)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/reviews", wrapper.AdminListReviews)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/reviews/{id}", wrapper.AdminGetReview)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/reviews/{id}/approve", wrapper.ApproveReview)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/reviews/{id}/reject", wrapper.RejectReview)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/reviews/{id}/response", wrapper.RespondToReview)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/review-settings", wrapper.GetReviewSettings)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/review-settings", wrapper.PutReviewSettings)
	})

	return r
}

