// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetReviewSettings Get the shop's review settings
	// (GET /admin/review-settings)
	GetReviewSettings(ctx context.Context, request GetReviewSettingsRequestObject) (GetReviewSettingsResponseObject, error)
	// PutReviewSettings Set the shop's review settings
	// (PUT /admin/review-settings)
	PutReviewSettings(ctx context.Context, request PutReviewSettingsRequestObject) (PutReviewSettingsResponseObject, error)
	// AdminListReviews List the shop's reviews
	// (GET /admin/reviews)
	AdminListReviews(ctx context.Context, request AdminListReviewsRequestObject) (AdminListReviewsResponseObject, error)
	// AdminGetReview Get a review
	// (GET /admin/reviews/{id})
	AdminGetReview(ctx context.Context, request AdminGetReviewRequestObject) (AdminGetReviewResponseObject, error)
	// ApproveReview Approve a review
	// (POST /admin/reviews/{id}/approve)
	ApproveReview(ctx context.Context, request ApproveReviewRequestObject) (ApproveReviewResponseObject, error)
	// RejectReview Reject a review
	// (POST /admin/reviews/{id}/reject)
	RejectReview(ctx context.Context, request RejectReviewRequestObject) (RejectReviewResponseObject, error)
	// RespondToReview Respond to a review
	// (PUT /admin/reviews/{id}/response)
	RespondToReview(ctx context.Context, request RespondToReviewRequestObject) (RespondToReviewResponseObject, error)
	// ListMyLikes List the products I like
	// (GET /likes)
	ListMyLikes(ctx context.Context, request ListMyLikesRequestObject) (ListMyLikesResponseObject, error)
	// UnlikeProduct Unlike a product
	// (DELETE /likes/{product_id})
	UnlikeProduct(ctx context.Context, request UnlikeProductRequestObject) (UnlikeProductResponseObject, error)
	// LikeProduct Like a product
	// (PUT /likes/{product_id})
	LikeProduct(ctx context.Context, request LikeProductRequestObject) (LikeProductResponseObject, error)
	// ListProductReviews List a product's reviews
	// (GET /reviews)
	ListProductReviews(ctx context.Context, request ListProductReviewsRequestObject) (ListProductReviewsResponseObject, error)
	// SubmitReview Review a product
	// (POST /reviews)
	SubmitReview(ctx context.Context, request SubmitReviewRequestObject) (SubmitReviewResponseObject, error)
	// ListMyReviews List my reviews
	// (GET /reviews/mine)
	ListMyReviews(ctx context.Context, request ListMyReviewsRequestObject) (ListMyReviewsResponseObject, error)
	// GetReviewStats A product's rating summary
	// (GET /reviews/stats)
	GetReviewStats(ctx context.Context, request GetReviewStatsRequestObject) (GetReviewStatsResponseObject, error)
	// DeleteReview Delete my review
	// (DELETE /reviews/{id})
	DeleteReview(ctx context.Context, request DeleteReviewRequestObject) (DeleteReviewResponseObject, error)
	// EditReview Edit my review
	// (PUT /reviews/{id})
	EditReview(ctx context.Context, request EditReviewRequestObject) (EditReviewResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

